@startuml

class BusRoute {
  + RouteNumber : int
}

class Bus {
  + LicencePlate : string
  + IsInRepairShop : boolean
}

class Driver {
  + DriverID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class ShiftType {
  + Morning
  + Afternoon
  + Night
}

class Assignment {
  + Date : date
  + Shift : ShiftType
}

BusRoute "1" -- "*" Bus : assigned to
BusRoute "1" -- "*" Assignment : has
Bus "1" -- "*" Assignment : assigned to
Driver "1" -- "*" Assignment : assigned to

@enduml

